import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.BV21bweQ.js";const g=JSON.parse('{"title":"狐族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/狐族.md","filePath":"表层/种族/狐族.md","lastUpdated":1787066340000}'),e={name:"表层/种族/狐族.md"};function i(n,a,s,h,u,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="狐族" tabindex="-1">狐族 <a class="header-anchor" href="#狐族" aria-label="Permalink to &quot;狐族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>狐族是黑暗时代出现的新兴种族，处境极为艰难。狐族<strong>全族皆为雌性</strong>，没有雄性，繁衍全靠其他种族，且后代只会是雌性狐族。这一繁衍特性使其在黑暗时代中天生沦为性奴隶的人选。如今狐族主要依附于狼族，是&quot;流亡/丧失主权的种族&quot;之一。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有狐狸类动物的典型福瑞形态。</li><li><strong>体型</strong>：普遍体型娇小，体态优雅，动作灵活。</li><li><strong>尾巴</strong>：拥有蓬松的大尾巴，是狐族的标志性特征。</li><li><strong>毛色</strong>：以红色、橙色、白色为主，常见多种毛色变种。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="繁衍特性" tabindex="-1">繁衍特性 <a class="header-anchor" href="#繁衍特性" aria-label="Permalink to &quot;繁衍特性&quot;">​</a></h3><p>狐族最显著的特征是<strong>全族没有雄性</strong>：</p><ul><li><strong>全雌种族</strong>：所有狐族成员均为雌性，历史上从未发现雄性狐族个体。</li><li><strong>繁衍依赖外族</strong>：繁衍全靠与其他种族交配。</li><li><strong>后代固化</strong>：与其他种族交配产生的后代<strong>没有其他种族的影子，只会是雌性狐族</strong>。</li><li><strong>无血脉外流风险</strong>：由于后代始终是狐族，不存在血脉外流风险——这使外族对狐族没有任何&quot;基因被稀释&quot;的顾虑，但也意味着狐族永远无法摆脱依附状态。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="黑暗时代-被排斥的种族" tabindex="-1">黑暗时代：被排斥的种族 <a class="header-anchor" href="#黑暗时代-被排斥的种族" aria-label="Permalink to &quot;黑暗时代：被排斥的种族&quot;">​</a></h3><p>黑暗时代中，狐族的种族特质使其被其余种族排斥，处境<strong>极差</strong>：</p><ul><li><strong>天生的性奴隶人选</strong>：因全族皆为雌性且后代不存在血脉外流风险，狐族天生成为性奴隶的人选，被大量用于服务业、红灯区。</li><li><strong>战乱中的弱势</strong>：作为新兴种族，狐族在战乱中处境极差，缺乏自保能力。</li></ul><h3 id="独立后的困境" tabindex="-1">独立后的困境 <a class="header-anchor" href="#独立后的困境" aria-label="Permalink to &quot;独立后的困境&quot;">​</a></h3><p>黑暗时代结束后，狐族获得了一定程度的独立，但<strong>即使独立后，仍旧因种族特质而难以争取主权与帮助</strong>：</p><ul><li>难以建立独立的种族政权与社会体系。</li><li>社会偏见长期存在，种族身份与黑暗时代的遭遇紧密关联。</li></ul><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>狐族目前<strong>主要依附于狼族</strong>，是&quot;流亡/丧失主权的种族&quot;之一：</p><ul><li><strong>依附生存</strong>：在狼族庇佑下建立城邦，获得基本生存保障，但政治与军事上完全受制于狼族。</li><li><strong>主权缺失</strong>：难以获得独立的种族主权，依附关系意味着安全，也意味着无法真正自主。</li></ul><p>此外，红星孤儿院的孤儿<strong>拉斯塔</strong>为狐族，是狐族中知名的个体。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>狐族繁衍特性的真实成因不属表层认知。</p></blockquote><ul><li><a href="./../../中层/人物/神机" class="layer-link" data-layer="中层">神机</a> —— 狐族繁衍特性的真相</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./狼族">狼族</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li><li><a href="./../../中层/人物/拉斯塔" class="layer-link" data-layer="中层">拉斯塔</a></li></ul><hr>',31)])])}const q=r(e,[["render",i]]);export{g as __pageData,q as default};
